function minFlips(grid) {
  const m = grid.length;
  const n = grid[0].length;
  let flips = 0;
  for (let top = 0, bottom = m - 1; top < bottom; top++, bottom--) {
    for (let left = 0, right = n - 1; left < right; left++, right--) {
      const ones = grid[top][left] + grid[top][right] + grid[bottom][left] + grid[bottom][right];
      flips += Math.min(ones, 4 - ones);
    }
  }
  let mismatched = 0;
  let onePairs = 0;
  if (m % 2 === 1) {
    const midRow = (m - 1) / 2;
    for (let left = 0, right = n - 1; left < right; left++, right--) {
      if (grid[midRow][left] !== grid[midRow][right]) {
        mismatched++;
      } else if (grid[midRow][left] === 1) {
        onePairs++;
      }
    }
  }
  if (n % 2 === 1) {
    const midCol = (n - 1) / 2;
    for (let top = 0, bottom = m - 1; top < bottom; top++, bottom--) {
      if (grid[top][midCol] !== grid[bottom][midCol]) {
        mismatched++;
      } else if (grid[top][midCol] === 1) {
        onePairs++;
      }
    }
  }
  if (m % 2 === 1 && n % 2 === 1) {
    flips += grid[(m - 1) / 2][(n - 1) / 2];
  }
  if (mismatched > 0) {
    flips += mismatched;
  } else if (onePairs % 2 === 1) {
    flips += 2;
  }
  return flips;
}

