function minFlips(grid) {
  // A row and column palindrome grid equals its mirror images, so each cell must share one value with the cells
  // that mirror it. Group the cells that way and try every choice of values for the groups.
  const m = grid.length, n = grid[0].length;
  const classes = new Map();
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      const key = Math.min(i, m - 1 - i) + ',' + Math.min(j, n - 1 - j);
      if (!classes.has(key)) classes.set(key, []);
      classes.get(key).push(grid[i][j]);
    }
  }
  const groups = [...classes.values()];
  let best = Infinity;
  for (let mask = 0; mask < 1 << groups.length; mask++) {
    let flips = 0, ones = 0;
    groups.forEach((cells, g) => {
      const value = (mask >> g) & 1;
      ones += value * cells.length;
      for (const cell of cells) if (cell !== value) flips++;
    });
    if (ones % 4 === 0) best = Math.min(best, flips);
  }
  return best;
}

