function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const shapes = size === 'large'
    ? [[100, 100], [99, 99], [100, 99], [99, 100], [1, 100], [100, 1], [pick(50, 100), pick(50, 100)]]
    : [[pick(1, 6), pick(1, 6)]];
  const [m, n] = shapes[Math.floor(rand() * shapes.length)];
  const density = rand();
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)));
  if (rand() < 0.5) {
    // Copy the top-left quarter onto its mirror images so the grid is palindromic, then flip a few cells.
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) grid[i][j] = grid[Math.min(i, m - 1 - i)][Math.min(j, n - 1 - j)];
    const changes = pick(0, 3);
    for (let c = 0; c < changes; c++) grid[pick(0, m - 1)][pick(0, n - 1)] ^= 1;
  }
  return [grid];
}
